const PLACEHOLDER='data:image/svg+xml;charset=utf-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="96" height="96"><rect x="3" y="3" width="90" height="90" rx="12" fill="#eef3fa" stroke="#8fa6c6"/><text x="48" y="44" text-anchor="middle" font-size="26" fill="#546d90">?</text><text x="48" y="68" text-anchor="middle" font-size="11" fill="#546d90">点击重试</text></svg>');
function pathOf(url){try{const u=new URL(url,SPRITE_BASE);const match=u.pathname.match(/\/(?:sprites|assets\/pokemon)\/((?:ani|ani-back|ani-shiny|ani-back-shiny|gen5|gen5-back|gen5-shiny|gen5-back-shiny)\/[^/]+\.(?:gif|png))$/);return match?.[1]||null}catch{return null}}
export function localSprite(url){const p=pathOf(url);return p&&paths.has(p)?new URL('assets/pokemon/'+p,SPRITE_BASE).href:url}
export function shinySprite(url){return String(url).replace('/ani/','/ani-shiny/').replace('/ani-back/','/ani-back-shiny/').replace('/gen5/','/gen5-shiny/').replace('/gen5-back/','/gen5-back-shiny/')}
export function spriteFallbacks(url){const p=pathOf(url);if(!p)return[];const upstream='https://play.pokemonshowdown.com/sprites/'+p;if(!paths.has(p))return[upstream];return [...new Set([new URL('assets/pokemon/'+p,SPRITE_BASE).href,new URL('assets/pokemon/static/'+p.replace(/\.(gif|png)$/,'.png'),SPRITE_BASE).href,upstream])];}
export function recoverSprite(img){if(!img)return false;let state=img.__pkmSpriteState;const current=img.currentSrc||img.src||'';if(!state||!state.urls.includes(current)){const urls=spriteFallbacks(current);if(!urls.length)return false;state=img.__pkmSpriteState={urls,index:Math.max(0,urls.indexOf(current))};}
img.onerror=null;img.style.visibility='visible';img.style.opacity='1';state.index++;
if(state.index<state.urls.length){img.src=state.urls[state.index];return true}
img.dataset.pkmSpriteRetry=state.urls[0];img.alt='图片暂不可用，点击重试';img.src=PLACEHOLDER;return true;}
export function installSpriteRecovery(doc){if(!doc||doc.__pkmSpriteRecoveryV1330)return;doc.__pkmSpriteRecoveryV1330=true;
doc.addEventListener('error',e=>{const t=e.target;if(t?.tagName!=='IMG')return;if(recoverSprite(t)){e.preventDefault();e.stopImmediatePropagation()}},true);
doc.addEventListener('load',e=>{const t=e.target;if(t?.tagName==='IMG'&&pathOf(t.currentSrc||t.src)){t.style.visibility='visible';delete t.dataset.pkmSpriteRetry;}},true);
doc.addEventListener('click',e=>{const t=e.target;if(t?.tagName==='IMG'&&t.dataset.pkmSpriteRetry){e.preventDefault();e.stopImmediatePropagation();t.__pkmSpriteState=null;t.src=t.dataset.pkmSpriteRetry;delete t.dataset.pkmSpriteRetry;}},true);
}
